using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Unity.Collections;
[InitializeOnLoad]public static class FinalPNGExtraSites{
const string ScenePath="Assets/Editor/DayNightBackups/Gangstar Final Env.unity",PrefabPath="Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab",Out="Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas";
static FinalPNGExtraSites(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalPNGExtraSites.request")||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;var mode=File.ReadAllText("FinalPNGExtraSites.request").Trim();File.Delete("FinalPNGExtraSites.request");if(mode=="finish"){Finish();return;}Run();}
class Road{public MeshFilter f;public Bounds b;public Vector4[] uv;public int tile;public float len;}
static Vector4[] UV(Mesh m,int channel){using(var all=MeshUtility.AcquireReadOnlyMeshData(m))using(var a=new NativeArray<Vector4>(all[0].vertexCount,Allocator.Temp)){all[0].GetUVs(channel,a);return a.ToArray();}}
static Mesh Save(Mesh m,string name){m.name=name;string path=Out+"/Meshes/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(m,old);UnityEngine.Object.DestroyImmediate(m);EditorUtility.SetDirty(old);return old;}AssetDatabase.CreateAsset(m,path);return m;}
static void Photo(Scene s,Vector3 p,string name){typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{s,p+Vector3.up*27,p,name});}
static void Finish(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath(ScenePath);var roadRoot=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var tuned=new Dictionary<MeshFilter,Mesh>();foreach(var f in roadRoot.GetComponentsInChildren<MeshFilter>(true).Where(f=>new[]{"polySurface788","polySurface787","polySurface813","polySurface779","polySurface824","polySurface863","polySurface866","polySurface880"}.Contains(f.name))){var uv=UV(f.sharedMesh,3);var b=f.GetComponent<Renderer>().bounds;float len=Mathf.Max(b.size.x,b.size.z);var m=UnityEngine.Object.Instantiate(f.sharedMesh);if(Mathf.FloorToInt(uv[0].x/32)==5){float repeats=Mathf.Max(1,len/35);for(int i=0;i<uv.Length;i++){uv[i].y=uv[i].y/uv[i].w*repeats;uv[i].w=repeats;}m.SetUVs(3,uv.ToList());}else{float repeats=uv[0].w;float centre=(Mathf.Floor(repeats*.5f)+.473f)/repeats;m.SetUVs(4,uv.Select(v=>new Vector4((v.x-2*32-16-.9f)/.13f+.5f,(v.y/v.w-centre)/(8/len)+.5f,20,-1)).ToList());}tuned.Add(f,Save(m,"PNG_TunedSite_"+f.name));}var roadPrefab=PrefabUtility.LoadPrefabContents(PrefabPath);try{foreach(var t in tuned){var path=AnimationUtility.CalculateTransformPath(t.Key.transform,roadRoot.transform);roadPrefab.transform.Find(path).GetComponent<MeshFilter>().sharedMesh=t.Value;}PrefabUtility.SaveAsPrefabAsset(roadPrefab,PrefabPath);}finally{PrefabUtility.UnloadPrefabContents(roadPrefab);}foreach(var t in tuned){t.Key.sharedMesh=t.Value;PrefabUtility.RecordPrefabInstancePropertyModifications(t.Key);}var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).ToArray();var parking=all.Where(f=>f.name.StartsWith("Plane.003_0")&&!f.name.StartsWith("Plane.003_002")&&f.GetComponent<Renderer>()).OrderBy(f=>f.GetComponent<Renderer>().bounds.SqrDistance(new Vector3(437.8f,27.74f,160.66f))).First();var bounds=parking.GetComponent<Renderer>().bounds;log.AppendLine("Parking target="+parking.name+" bounds="+bounds);var pm=UnityEngine.Object.Instantiate(parking.sharedMesh);Vector3[] points;using(var md=MeshUtility.AcquireReadOnlyMeshData(pm))using(var a=new NativeArray<Vector3>(md[0].vertexCount,Allocator.Temp)){md[0].GetVertices(a);points=a.ToArray();}var bay=new Vector3(bounds.center.x+.06f,27.74f,bounds.center.z+2.81f);pm.SetUVs(4,points.Select(v=>{var p=parking.transform.TransformPoint(v);return new Vector4((p.x-bay.x)/1.6f+.5f,(p.z-bay.z)/5f+.5f,19,-1);}).ToList());pm=Save(pm,"PNG_NoParking_AccessAisle");parking.sharedMesh=pm;var renderer=parking.GetComponent<MeshRenderer>();renderer.sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>(Out+"/City PNG Parking Cafe.mat");PrefabUtility.RecordPrefabInstancePropertyModifications(parking);PrefabUtility.RecordPrefabInstancePropertyModifications(renderer);string parkPrefab=Out+"/PNG Plane.003_0.prefab";var pref=PrefabUtility.LoadPrefabContents(parkPrefab);try{pref.GetComponentsInChildren<MeshFilter>(true).First().sharedMesh=pm;PrefabUtility.SaveAsPrefabAsset(pref,parkPrefab);}finally{PrefabUtility.UnloadPrefabContents(pref);}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");foreach(var f in root.GetComponentsInChildren<MeshFilter>(true).Where(f=>new[]{"polySurface788","polySurface805","polySurface863","polySurface789","polySurface809"}.Contains(f.name))){Photo(scene,f.GetComponent<Renderer>().bounds.center,"ExtraPNG-"+f.name);}Photo(scene,bay,"ExtraPNG-NoParking");log.AppendLine("SUCCESS: completed 15 sites: 5 ONLY, 4 BUS LANE, 3 cycle, 2 TAXI and 1 NO PARKING access aisle. Scene and prefabs saved.");}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/PNGExtraSitesFinish.txt",log.ToString());}
static void Run(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath(ScenePath);var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var roads=root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh&&f.sharedMesh.HasVertexAttribute(UnityEngine.Rendering.VertexAttribute.TexCoord3)&&f.GetComponent<MeshRenderer>()&&f.GetComponent<MeshRenderer>().sharedMaterial&&f.GetComponent<MeshRenderer>().sharedMaterial.name=="City PNG Markings").Select(f=>{var uv=UV(f.sharedMesh,3);var b=f.GetComponent<Renderer>().bounds;return new Road{f=f,uv=uv,b=b,tile=Mathf.FloorToInt(uv[0].x/32),len=Mathf.Max(b.size.x,b.size.z)};}).ToArray();var landmarks=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>r.gameObject.activeInHierarchy&&!r.transform.IsChildOf(root.transform)).ToArray();var bus=landmarks.Where(r=>(r.name+" "+string.Join(" ",r.sharedMaterials.Where(m=>m).Select(m=>m.name))).ToLowerInvariant().Contains("bus")).ToArray();var shops=landmarks.Where(r=>string.Join(" ",r.sharedMaterials.Where(m=>m).Select(m=>m.name)).ToLowerInvariant().Contains("cafe")||r.name.ToLowerInvariant().Contains("hotel")||r.name.ToLowerInvariant().Contains("casino")).ToArray();var junctions=roads.Where(r=>r.tile>=8&&r.tile<=11).ToArray();var used=new HashSet<MeshFilter>();var changes=new Dictionary<MeshFilter,Mesh>();string stamp=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");EditorSceneManager.SaveScene(scene,"FinalEnvironmentRoadBackup/BeforeExtraPNGSites-"+stamp+".unity",true);File.Copy(PrefabPath,"FinalEnvironmentRoadBackup/BeforeExtraPNGSites-"+stamp+".prefab");
Func<Road,bool> eligible=r=>r.tile==0&&r.len>60&&r.b.size.y<3&&Mathf.Min(r.b.size.x,r.b.size.z)>24&&Mathf.Min(r.b.size.x,r.b.size.z)<35;
var only=roads.Where(eligible).Where(r=>junctions.Any(j=>r.b.SqrDistance(j.b.center)<600)).OrderBy(r=>junctions.Min(j=>r.b.SqrDistance(j.b.center))).Take(5).ToArray();if(only.Length<5)throw new Exception("Not enough suitable turn approaches");
foreach(var r in only){var m=UnityEngine.Object.Instantiate(r.f.sharedMesh);var uv=(Vector4[])r.uv.Clone();for(int i=0;i<uv.Length;i++){uv[i].x=5*32+16+(uv[i].x-r.tile*32-16);uv[i].y/=uv[i].w;uv[i].w=1;}m.SetUVs(3,uv.ToList());changes.Add(r.f,Save(m,"PNG_ONLY_"+r.f.name));used.Add(r.f);log.AppendLine("ONLY beneath turn arrows: "+r.f.name);}
Action<Road,int,Renderer> patch=(r,code,landmark)=>{float u=.895f;if(code==20)u=.9f;else if(landmark){Vector3[] p;using(var all=MeshUtility.AcquireReadOnlyMeshData(r.f.sharedMesh))using(var a=new NativeArray<Vector3>(all[0].vertexCount,Allocator.Temp)){all[0].GetVertices(a);p=a.ToArray();}var low=Enumerable.Range(0,p.Length).Where(i=>r.uv[i].x-r.tile*32-16<.25).Select(i=>r.f.transform.TransformPoint(p[i])).ToArray();var high=Enumerable.Range(0,p.Length).Where(i=>r.uv[i].x-r.tile*32-16>.75).Select(i=>r.f.transform.TransformPoint(p[i])).ToArray();if(low.Length>0&&high.Length>0)u=low.Min(v=>landmark.bounds.SqrDistance(v))<high.Min(v=>landmark.bounds.SqrDistance(v))?.135f:.895f;}float wu=code==20?.13f:.17f;float length=code==17?10:code==18?14:8;var site=r.uv.Select(v=>{float a=(v.x-r.tile*32-16-u)/wu+.5f;float b=(v.y/v.w-.5f)/(length/r.len)+.5f;if(u>.5f){a=1-a;b=1-b;}return new Vector4(a,b,code,-1);}).ToList();var m=UnityEngine.Object.Instantiate(r.f.sharedMesh);m.SetUVs(4,site);changes.Add(r.f,Save(m,"PNG_Site_"+r.f.name));used.Add(r.f);log.AppendLine("Site code="+code+" road="+r.f.name+" curb lane="+u+" landmark="+(landmark?landmark.name:"existing cycle lane"));};
var busRoads=roads.Where(eligible).Where(r=>!used.Contains(r.f)).OrderBy(r=>bus.Min(b=>b.bounds.SqrDistance(r.b.center))).Take(4).ToArray();foreach(var r in busRoads)patch(r,18,bus.OrderBy(b=>b.bounds.SqrDistance(r.b.center)).First());var cycle=roads.Where(r=>r.tile==2&&r.len>60).OrderBy(r=>r.len).Take(3).ToArray();foreach(var r in cycle)patch(r,20,null);var taxi=roads.Where(eligible).Where(r=>!used.Contains(r.f)).OrderBy(r=>shops.Min(b=>b.bounds.SqrDistance(r.b.center))).Take(2).ToArray();foreach(var r in taxi)patch(r,17,shops.OrderBy(b=>b.bounds.SqrDistance(r.b.center)).First());if(changes.Count!=14)throw new Exception("Expected 14 road sites");
var pref=PrefabUtility.LoadPrefabContents(PrefabPath);try{foreach(var c in changes){var path=AnimationUtility.CalculateTransformPath(c.Key.transform,root.transform);pref.transform.Find(path).GetComponent<MeshFilter>().sharedMesh=c.Value;}PrefabUtility.SaveAsPrefabAsset(pref,PrefabPath,out bool ok);if(!ok)throw new Exception("Road prefab save failed");}finally{PrefabUtility.UnloadPrefabContents(pref);}foreach(var c in changes){c.Key.sharedMesh=c.Value;PrefabUtility.RecordPrefabInstancePropertyModifications(c.Key);}
var parking=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Single(f=>f.name=="Plane.003_0");var pm=UnityEngine.Object.Instantiate(parking.sharedMesh);Vector3[] points;using(var all=MeshUtility.AcquireReadOnlyMeshData(pm))using(var a=new NativeArray<Vector3>(all[0].vertexCount,Allocator.Temp)){all[0].GetVertices(a);points=a.ToArray();}pm.SetUVs(4,points.Select(v=>{var p=parking.transform.TransformPoint(v);return new Vector4((p.x-437.8f)/1.6f+.5f,(p.z-160.66f)/5f+.5f,19,-1);}).ToList());pm=Save(pm,"PNG_NoParking_AccessAisle");parking.sharedMesh=pm;PrefabUtility.RecordPrefabInstancePropertyModifications(parking);string parkPrefab=Out+"/PNG Plane.003_0.prefab";var pp=PrefabUtility.LoadPrefabContents(parkPrefab);try{pp.GetComponentsInChildren<MeshFilter>(true).Single(f=>f.name=="Plane.003_0").sharedMesh=pm;PrefabUtility.SaveAsPrefabAsset(pp,parkPrefab);}finally{PrefabUtility.UnloadPrefabContents(pp);}log.AppendLine("NO PARKING in existing hatched accessible-parking access aisle on Plane.003_0.");
AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);foreach(var r in busRoads.Take(1).Concat(cycle.Take(1)).Concat(taxi.Take(1)).Concat(only.Take(1)))Photo(scene,r.b.center,"ExtraPNG-"+r.f.name);Photo(scene,new Vector3(437.8f,27.74f,160.66f),"ExtraPNG-NoParking");log.AppendLine("SUCCESS: 15 logical sites: 5 ONLY approaches, 4 BUS LANE bays, 3 red cycle patches, 2 TAXI bays, 1 NO PARKING access aisle. Same PNG atlas. Scene and prefabs saved.");}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/PNGExtraSites.txt",log.ToString());}
}




